\section{Simulation Theorems for Other Variants} 
 In this section, we will prove weaker variants of Conjecture \ref{CHFSgeneral} and show that these variants imply Conjecture \ref{thm:main} for additional variants of parallel quantum algorithms, including paralel quantum algorithms with limited adaptivity. 

\subsection{Simulation Theorem for Hybrid Quantum Algorithms}\label{sec:hybrid_quantum}

\begin{theorem}[A weaker variant of Conjecture \ref{CHFSgeneral}]\label{CHFS_classical}
  Let $O_X$ be a $(1-\delta)$-dense distribution and $O_U$ be a uniform distribution. Let $\mathcal{M}_C$ denote  the modification algorithm in Algorithm \ref{modalg:classical}. 
  Let $\text{Flip}_{O,\mathcal{M}_C}$ denote the set of all coordinates that $\mathcal{M}_C$ flips on input $O$. 
    Then there exist absolute constants $C,a \geq 0, b > 0$ such that, for every $T$ query classical algorithm $\mathcal{A}$ outputting a coordinate $i$, we have 
    \begin{align*}
        \Pr_{O \sim O_X,\mathcal{A}, \mathcal{M}_C}\left[\mathcal{A}^O \to i \, \wedge \,  i \in \text{Flip}_{O,\mathcal{M}_C}\right] \leq C \cdot T^a\cdot \delta^b.
    \end{align*}
\end{theorem}




\begin{theorem}[A weaker variant of Conjecture \ref{thm:main}]
\label{thm:main_classcial+parallel}
    Let $O_X$ be a $(1-\delta)$-dense distribution over oracles $O:[N] \to \{0,1\}$ and  $O_U$ be uniform.
    There exist absolute constants $C,a \geq 0, b > 0$  such that for all quantum algorithms $\As$ making $r$ (adaptive)  classical queries followed by $T$ parallel quantum queries 
    \[
    \Big|\Pr_{O \sim O_X}[\mathcal{A}^O \rightarrow 1]-\Pr_{O \sim O_U}[\mathcal{A}^O \rightarrow 1]\Big|\leq  C\cdot  (T + r)^a  \cdot \delta^b
    \]
\end{theorem}
\noindent Note that \Cref{thm:main_classcial+parallel} reproves the classical dense indistinguishability theorem when we set $T = 0$, with worse parameters compared to Claim 3~\cite{coretti2018random}.

\begin{lemma}\label{hybrid_CHFS_imply}
    Theorem  \ref{CHFS_classical} implies Theorem \ref{thm:main_classcial+parallel}.
\end{lemma}
\begin{proof}

   Let $\mathcal{A}$ be the quantum algorithm making $r$ classical queries followed by $T$ parallel queries to an oracle $O$ drawn from either $O_X$ or $O_U$. For $t \in [r+1]$, denote $\ket {\phi_t^O}$ to be the quantum state of the algorithm $\mathcal{A}$ right before the $t$-th query under oracle $O$; if $t = r+1$, it denotes the last layer of parallel quantum queries.

  By Theorem \ref{thm:bbbv97} and Theorem \ref{thm:parallelbbbv}, the distinguishing advantage is bounded by 
    \begin{align*}
       \mathbb{E}_{O\sim O_X, \mathcal{M}_C} \left[ \sqrt{ (r+1) \cdot \left( \sum_{t=1}^{r}\sum_{i \in \text{Flip}_{ O, \mathcal{M}_C}} W_i\left( \ket{\phi_t^O} \right) + \sum_{i \in \text{Flip}_{ O, \mathcal{M}_C}} W_i\left( \ket{\phi_{r+1}^O} \right)  \right) }\right],
    \end{align*}
    where $W_i$ in the second summation denotes the probability that when measuring all $T$ query registers, (at least) one of the outcomes is equal to $i$. 
    By the concavity of $\sqrt{x}$ and linearity of expectation, we have it is at most
    \begin{align*}
        \sqrt{r+1} \cdot \sqrt{\sum_{t=1}^r\mathbb{E}_{O\sim O_X, \mathcal{M}_C} \left[ \sum_{i \in \text{Flip}_{ O, \mathcal{M}_C}} W_i\left( \ket{\phi_t^O} \right)  \right] +  \mathbb{E}_{O\sim O_X, \mathcal{M}_C} \left[\sum_{i \in \text{Flip}_{ O, \mathcal{M}_C}}W_i\left( \ket{\phi_{r+1}^O} \right)  \right]}.
    \end{align*}
   As long as the term $\mathbb{E}_{O\sim O_X, \mathcal{M}_C} \left[ \sum_{i \in \text{Flip}_{ O, \mathcal{M}_C}} W_i\left( \ket{\phi_{t}^O} \right)  \right]$ is small for all $t \in [r+1]$, we can conclude the proof. 






    By \Cref{CHFS_classical}, the distinguishing advantage is at most  $\sqrt{C  \cdot (r+1) (T+r) \cdot r^a \cdot \delta^b}$.



\end{proof}

The rest of this section is dedicated to proving Theorem \ref{CHFS_classical}.
\paragraph{Proof of Theorem \ref{CHFS_classical}}
\begin{proof}
Let $\mathcal{A}$ be any $t$ query classical algorithm, and 
let $\mathbf{z}=(\mathbf{i_1},\mathbf{y_1}), \dots (\mathbf{i_t},\mathbf{y_t})$ be  the random transcript obtained by making $t$ queries to $O \sim O_X$. For all $z \sim \bf{z}$, for all $j \in [t]$, let $z_j:= (i_1,y_1), \dots (i_j,y_j)$, and let $O_X^{z_j}$ denote the distribution $O_X$ conditioned on $\mathbf{z_j}=z_j$. Let $M^*$ denote the modifying algorithm in Theorem \ref{strongchangeoracle}. Then, define the modifying algorithm $\mathcal{M}_C$ to be the following:
\begin{algorithm}
\caption{Modification Algorithm $\mathcal{M}_{C}$}\label{modalg:classical}
\begin{algorithmic}
\State \textbf{Input:} $O=(x_1,\dots,x_N)\sim O_X$
\State Run $\mathcal A^O$  and let $z=((i_1,y_1),\dots,(i_t,y_t))$
be the resulting transcript. 

\For{$j=1,\dots,t$}
    \State Let $z_{j-1}:=((i_1,y_1),\dots,(i_{j-1},y_{j-1}))$
    \State Let
    \[
    q_{i_j,b}:=\Pr_{O'\sim O_X^{z_{j-1}}}[\,O'(i_j)=b\,]
    \qquad\text{for each } b\in\{0,1\}
    \]
    \State Let $b:=y_j$
    \If{$q_{i_j,b} > \tfrac12$}
        \State Set $\tilde x_{i_j}\gets 1-b$ with probability $\frac{q_{i_j,b}-1/2}{q_{i_j,b}}$,
        and otherwise set $\tilde x_{i_j}\gets b$.
    \Else
        \State Set $\tilde x_{i_j}\gets b$.
    \EndIf
\EndFor
\State Sample the remaining coordinates
\[
(\tilde x_i)_{i\in [N]\setminus \{i_1,\dots,i_t\}}
\]
according to  Algorithm  $M^*$ from Theorem \ref{thm:strongchangeoracle} applied to the conditional distribution $O_X^z$.

\State \textbf{Output:} $\tilde O=(\tilde x_1,\dots,\tilde x_N)$
\end{algorithmic}
\end{algorithm}

 \begin{claim}
     Algorithm $\mathcal{M}_C$ outputs the uniform distribution.
 \end{claim}
\begin{proof}
  For $j \leq t$, $\mathcal{M}_C$, produces a uniformly random coordinate for each queried coordinate $i_j$, by the same analysis as Algorithm \ref{alg:ModificationalgM}. 
  Conditioned on the transcript $z$, the remaining coordinates are distributed
according to $O_X^z$. Applying $M^*$ to these coordinates yields a uniform
distribution over $[N]\setminus \{i_1,\dots,i_t\}$.
\end{proof}


\noindent Now we will establish an upper bound on the winning probability of a $t$ query classical adversary $\mathcal{A}$. 
For a transcript $z= (i_1,y_1), \dots (i_t,y_t)$, define $\mathrm{qry}(z)= \{i_1, \dots i_t\}$. Define $\mathrm{qry}(z)_j$ be the $j$-th input $i_j$.

\begin{align*}
     &\Pr_{O \sim O_X, \mathcal{A}, \mathcal{M}_C} [\mathcal{A}^O \rightarrow i \wedge i \in \text{Flip}_{O,\mathcal{M}_C}]\\
     =& \Pr_{O \sim O_X,\mathcal{A}, \mathcal{M}_C} [\mathcal{A}^O \rightarrow i \wedge i \in \text{Flip}_{O,\mathcal{M}_C} \wedge i \in \mathrm{qry}(z)] + \Pr_{O \sim O_X,\mathcal{A}, \mathcal{M}_C} [\mathcal{A}^O \rightarrow i \wedge i \in \text{Flip}_{O,\mathcal{M}_C} \wedge i \not\in \mathrm{qry}(z)]\\
     \leq& \Pr_{O \sim O_X,\mathcal{A}, \mathcal{M}_C} [\exists i \in \mathrm{qry}(z), i \in \text{Flip}_{O, \mathcal{M}_C}] + \Pr_{O \sim O_X,\mathcal{A}, \mathcal{M}_C} [\mathcal{A}^O \rightarrow i \wedge i \in \text{Flip}_{O,\mathcal{M}_C} \wedge i \not\in \mathrm{qry}(z)] \\
     \leq& \sum_{j=1}^t \Pr_{O \sim O_X,\mathcal{A}, \mathcal{M}_C} [\mathrm{qry}(z)_j \in \text{Flip}_{O, \mathcal{M}_C}] + \Pr_{O \sim O_X,\mathcal{A}, \mathcal{M}_C} [\mathcal{A}^O \rightarrow i \wedge i \in \text{Flip}_{O,\mathcal{M}_C} \wedge i \not\in \mathrm{qry}(z)].
\end{align*}

We will complete the proof using Lemma \ref{lem:queried_dense} and Lemma \ref{lemma:avgdensesmall}, which are proved below. 

\begin{lemma}\label{lem:queried_dense}
Let $\bf{z}=(i_1,y_1), \dots, (i_t,y_t)$ denote the random transcript obtained by making $t$ queries to $O \sim O_X$, and for all $z \sim \bf{z}$, let $\mathrm{qry}(z):= \{i_1, \dots, i_t\}$. Then
    \[
    \sum_{j=1}^t\Pr_{\substack{O\sim O_X \\ A, \mathcal{M}_C}}[\mathrm{qry}(z)_j \in \text{Flip}_{O,\mathcal{M}_C}]\leq \sqrt{\frac{\delta \cdot \ln 2}{2}} \cdot t.
    \]
 \end{lemma}
\begin{proof}
The proof is similar to that of Lemma \ref{changeoracle}, except the order is adaptive. We will prove this theorem for deterministic classical algorithms; this will easily extends to  randomized algorithms (which is a convex combination of deterministic algorithms). 

The modification algorithm flips the distribution according to the order $i_1, i_2, \ldots, i_t$, where each $i_j$ itself is a random variable. Similar to Lemma \ref{changeoracle}, for all $j \in  \{0, 1, \ldots, t-1\}$ and $x \in \{0,1\}^j$, $p_x$ is defined as the probability that the outcome for the first $j$ queries is $x$.  Since the algorithm is deterministic, once $x$ is fixed, we know $i_1, i_2, \ldots, i_t$. Let $q_{x, b}$ be the conditional probability that the next bit is $b$ conditioned on the transcript $x$ so far. Define $e_x = |q_{x, 0} - 1/2| = |q_{x, 1} - 1/2|$. The quantity we want to bound can be represented by $\sum_{j=0}^{t-1} p_x e_x$. 

Since $\{p_x\}_{x \in \{0,1\}^j}$ is induced by a classical deterministic decision tree, we have that $\{p_x\}_x$ is a distribution, it is $(1-\delta)$-dense and thus has Shannon entropy at least $(1-\delta) j$. 
Therefore, following the identical entropy argument and Cauchy-Schwarz in Lemma \ref{changeoracle}, we have
\begin{align*}
    \sum_{j=0}^{t-1} p_x e_x \leq \sqrt{\frac{\ln 2}{2} \delta} \cdot t.
\end{align*}
\end{proof}

Now we bound the second term. 
\begin{lemma}
\label{lemma:avgdensesmall}
     Let $O_X$ be a $(1-\delta)$ dense distribution, and let $\mathcal{A}$ be a classical algorithm that makes $t$ queries to $O \sim O_X$. Let $\bf{z}= (i_1,y_1), \dots (i_t,y_t)$ be the random variable over $([N]\times \{0,1\})^t$ of the transcript obtained by $\mathcal{A}$, and for all $z= (i_1,y_1), \dots (i_t,y_t)$ in the support of $\bf{z}$, let $\mathrm{qry(z)}:= \{i_1, \dots i_t\}$ denote the set of queried points.  Let $O^{z}_{X}$ denote the distribution of the restriction $O_{|N\setminus\mathrm{qry(z)}}$, where $O \sim O_X$ conditioned on $\mathbf{z}=z$. Let $\delta_z$ be the smallest real number such that $O^z_X$ is $(1-\delta_z)$ dense. Then
    \[
    \mathbb{E}_{z \sim \bf{z}}[\delta_z]\leq \delta \cdot (t+1), 
    \]
    where the randomness of the expectation is taken over $O \sim O_X$ and the classical algorithm $A$.
\end{lemma}

Given the above lemma, we can bound the second term.
\begin{align*}
    & \Pr_{O \sim O_X} [A^O \rightarrow i \wedge i \in \text{Flip}_{O,\mathcal{M}_C} \wedge i \not\in \mathrm{qry}(z)] \\
    &= \sum_{z  \sim \mathbf{z}} \Pr_{O \sim O_X,\mathcal{A}}[z]\cdot  \Pr_{O \sim O_X,\mathcal{A},\mathcal{M}_C} [A^O \rightarrow i \wedge i \in \text{Flip}_{O,\mathcal{M}_C} \wedge i \not\in \mathrm{qry}(z)|z]\\
    &= \sum_{z  \sim \mathbf{z}} \Pr_{O \sim O_X,\mathcal{A}}[z]\sum_{i} \Pr[\mathcal{A}^O\rightarrow i]\cdot  \Pr_{O \sim O_X,\mathcal{M}_C} [ i \in \text{Flip}_{O,\mathcal{M}_C} \wedge i \not\in \mathrm{qry}(z)|z,\mathcal{A}^O\rightarrow i]\\
    &\leq \sum_{z  \sim \mathbf{z}} \Pr_{O \sim O_X}[z] \cdot \max_{i^*\not\in \mathrm{qry}(z)} \Pr_{O \sim O^z_X}[i^* \in \text{Flip}_{O,\mathcal{M}_C}] \\
     &= \sum_{z  \sim \mathbf{z}} \Pr_{O \sim O_X}[z] \cdot \sqrt{\frac{\ln 2}{2} \cdot \delta_z} \\
     &\leq \sqrt{\frac{\ln 2}{2} \cdot \mathbb{E}_{z  \sim \mathbf{z}} [\delta_z]}.\\
    &\leq \sqrt{\frac{\ln 2}{2} \cdot \delta \cdot (t+1)}
\end{align*}

Finally, we prove Lemma \ref{lemma:avgdensesmall} .
\begin{proof}[Proof for Lemma \ref{lemma:avgdensesmall}]
We will prove this theorem for deterministic classical algorithms; this will easily extends to  randomized algorithms (which is a convex combination of deterministic algorithms). 

Fix a realization $z = (i_1,y_1), \dots (i_t,y_t)$ of $\bf{z}$. Let $S \subseteq [N]\setminus \{i_1, \dots i_t\}$.  
     \begin{align*}
         &\Pr_{O \sim O_X^z}[O(S)=y_S]\\
         &= \frac{ \Pr_{O \sim O_X}[O(S)=y_S\wedge O(i_1)=y_1, \dots O(i_t)= y_t]}{\Pr_{O \sim O_X}[O(i_1)=y_1, \dots O(i_t)= y_t]}\\
         &\leq \frac{2^{-(1-\delta)\cdot (|S|+t)}}{\Pr_{O \sim O_X}[O(i_1)=y_1, \dots O(i_t)= y_t]}\\
         &= \frac{2^{-(1-\delta)\cdot (|S|+t)}}{\Pr[z]}.
     \end{align*}
    Since the distribution $O_X^z$ is $(1-\delta_z)$ dense, this implies that
    \begin{align*}
         \frac{2^{-(1-\delta)\cdot (|S|+t)}}{\Pr[z]} \leq 2^{-(1-\delta_z)\cdot |S|}. 
    \end{align*}
   Therefore, 
   \[
   \delta_z\geq \delta + (-t+\delta \cdot t- \log (\Pr[z])) / |S|.
   \]
   Observe that  $ -t+\delta \cdot t- \log (\Pr[z]) \geq -(1-\delta) t+(1-\delta) t \geq 0$ due to denseness.


  Since for all sets $S$ such that $|S| \leq N-t$, we want $\delta_z\geq \delta \cdot |S|-t+\delta \cdot t- \log (\Pr[z])$, we will set $|S|=1$, since $\delta_z$ is maximized when $|S|=1$.

  Thus 
  \[\delta_z:= \delta(t+1)-t-\log (\Pr[z]).\]

   Now, 
   \begin{align*}
       \mathbb{E}_{z \sim \bf{z}}[\delta_z] & = \sum_{z}\Pr[z]\cdot \delta_z\\
       &= \sum_z \Pr[z]\cdot \Big(\delta(t+1)-t-\log (\Pr[z])\Big)\\
       &= \delta \cdot (t+1)-t+\sum_{z}\Pr[z]\log (1/\Pr[z])\\
       &= \delta \cdot (t+1)-t+ H(\bf{z})\\
       &\leq \delta \cdot (t+1).
    \end{align*}
    The last inequality is due to $H({\bf{z}})\leq t$, since $z$ is a transcript produced by a deterministic classical decision tree making $t$ queries. 
 \end{proof}

 Combining both lemmas, we conclude the proof.

\end{proof}




















